using System;
using System.Collections.Generic;
using System.Threading;
using System.IO;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;

namespace MonitoringAgent
{
    public sealed class FeatureFlags
    {
        private volatile Dictionary<string, bool> _flags = new Dictionary<string, bool>();
        private readonly object _lock = new object();

        public void Update(Dictionary<string, bool> newFlags)
        {
            lock (_lock)
            {
                _flags = new Dictionary<string, bool>(newFlags);
            }
        }

        public bool IsEnabled(string flag)
        {
            var snapshot = _flags;
            return snapshot.TryGetValue(flag, out var val) && val;
        }
    }

    public sealed class SecureLogBuffer
    {
        private readonly List<string> _buffer = new List<string>();
        private readonly object _bufferLock = new object();
        private volatile int _flushState = 0; // 0=idle, 1=flushing
        private readonly string _outputPath;
        private readonly FeatureFlags _features;

        public SecureLogBuffer(string outputPath, FeatureFlags features)
        {
            _outputPath = Path.GetFullPath(outputPath);
            _features = features;
        }

        public void Append(string entry)
        {
            if (string.IsNullOrEmpty(entry)) return;
            var sanitized = SanitizeEntry(entry);
            lock (_bufferLock)
            {
                _buffer.Add(sanitized);
            }
        }

        public bool TryFlushToDisk()
        {
            if (Interlocked.CompareExchange(ref _flushState, 1, 0) != 0)
            {
                return false; // Another flush in progress, skip
            }
            try
            {
                List<string> snapshot;
                lock (_bufferLock)
                {
                    snapshot = new List<string>(_buffer);
                    _buffer.Clear();
                }
                WriteEntries(snapshot);
                return true;
            }
            finally
            {
                Interlocked.Exchange(ref _flushState, 0);
            }
        }

        private void WriteEntries(List<string> entries)
        {
            using (var fs = new FileStream(_outputPath, FileMode.Append, FileAccess.Write, FileShare.None))
            using (var writer = new StreamWriter(fs, Encoding.UTF8))
            {
                foreach (var entry in entries)
                {
                    writer.WriteLine(entry);
                }
            }
        }

        private string SanitizeEntry(string entry)
        {
            return entry.Replace("\r", "").Replace("\n", " ");
        }
    }

    public sealed class SignalCoordinator
    {
        private readonly SecureLogBuffer _logBuffer;
        private readonly FeatureFlags _features;
        private readonly CancellationTokenSource _cts = new CancellationTokenSource();
        private volatile int _signalReceived = 0;
        private readonly ManualResetEventSlim _shutdownEvent = new ManualResetEventSlim(false);
        private Thread _workerThread;

        public SignalCoordinator(SecureLogBuffer logBuffer, FeatureFlags features)
        {
            _logBuffer = logBuffer;
            _features = features;
        }

        public void Start()
        {
            _workerThread = new Thread(WorkerLoop) { IsBackground = true, Name = "MonitorWorker" };
            _workerThread.Start();
            RegisterSignalHandlers();
        }

        private void RegisterSignalHandlers()
        {
            Console.CancelKeyPress += OnCancelSignal;
            AppDomain.CurrentDomain.ProcessExit += OnProcessExit;
        }

        private void OnCancelSignal(object sender, ConsoleCancelEventArgs e)
        {
            e.Cancel = true;
            HandleTerminationSignal();
        }

        private void OnProcessExit(object sender, EventArgs e)
        {
            HandleTerminationSignal();
        }

        private void HandleTerminationSignal()
        {
            if (Interlocked.CompareExchange(ref _signalReceived, 1, 0) == 0)
            {
                _cts.Cancel();
                // Always wait for worker to finish before flushing
                _shutdownEvent.Wait(TimeSpan.FromSeconds(5));
                // Worker is done, safe to flush - no concurrent access possible
                _logBuffer.TryFlushToDisk();
            }
        }

        private void WorkerLoop()
        {
            try
            {
                while (!_cts.Token.IsCancellationRequested)
                {
                    _logBuffer.Append("[HEARTBEAT] " + DateTime.UtcNow.ToString("o"));

                    if (_features.IsEnabled("periodic_flush"))
                    {
                        _logBuffer.TryFlushToDisk();
                    }

                    Thread.Sleep(1000);
                }
            }
            finally
            {
                _shutdownEvent.Set();
            }
        }

        public void WaitForShutdown()
        {
            _workerThread?.Join();
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            var features = new FeatureFlags();
            features.Update(new Dictionary<string, bool>
            {
                { "graceful_shutdown", true },
                { "flush_on_exit", true },
                { "periodic_flush", true }
            });

            var logPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "agent.log");
            var buffer = new SecureLogBuffer(logPath, features);
            var coordinator = new SignalCoordinator(buffer, features);

            coordinator.Start();
            coordinator.WaitForShutdown();
        }
    }
}
